window.adjustHeaderHeights=adjustHeaderHeights;function adjustHeaderHeights(){const topscreenInfoBlock=$('.topscreen-info-block');const headerMobile=$('.header-mobile');const headerBlock=$('.header-block');const headerMobileMenu=$('.header-mobile-menu');const infoBlockHeight=topscreenInfoBlock.outerHeight();const headerMobileHeight=headerMobile.is(':visible')?headerMobile.outerHeight():0;document.documentElement.style.setProperty('--topscreen-info-height',infoBlockHeight+'px');headerMobile.css('top',infoBlockHeight+'px');headerBlock.css('padding-top',(headerMobileHeight+infoBlockHeight)+'px');headerMobileMenu.css('top',(headerMobileHeight+infoBlockHeight)+'px')}
function initMobileMenu(){$(document).off('click.mobileMenu','.js-mobile-menu-btn').on('click.mobileMenu','.js-mobile-menu-btn',function(){$('body').toggleClass('menu-open overflow-hidden')});$(document).off('click.mobileSearch','.js-mobile-search-btn').on('click.mobileSearch','.js-mobile-search-btn',function(){$('.js-mobile-search').toggleClass('open')});const topscreenInfoBlock=$('.topscreen-info-block');if(topscreenInfoBlock.children('div.alert').length>0){adjustHeaderHeights();new ResizeObserver(adjustHeaderHeights).observe(topscreenInfoBlock?.[0])}}
function handleResize(){if(window.innerWidth<=767){initMobileMenu()}else{$('body').removeClass('menu-open overflow-hidden')}}
function debounce(func,wait){let timeout;return function executedFunction(...args){const later=()=>{clearTimeout(timeout);func(...args)};clearTimeout(timeout);timeout=setTimeout(later,wait)}}
function initCaptchaPreloader(){const $containers=$('.cf-turnstile');if(!$containers.length)return;$containers.each(function(){const $captcha=$(this);if($captcha.data('preloader-initialized'))return;const $wrapper=$('<div class="turnstile-preloader-wrapper"></div>');const $preloader=$('<div class="turnstile-preloader-preloader shimmer-background"></div>');$captcha.before($wrapper);$wrapper.append($captcha);$wrapper.append($preloader);$captcha.data('preloader-initialized',!0);const $form=$captcha.closest('form');const $submitBtn=$form.find('button[type="submit"]');const $submitLink=$form.find('.btn')
if($submitBtn.length){$submitBtn.prop('disabled',!0)}else if($submitLink.length){$submitLink.addClass('disabled')}
const destroy=()=>{$preloader.remove();if($submitBtn.length){$submitBtn.prop('disabled',!1)}else if($submitLink.length){$submitLink.removeClass('disabled')}
if(observer){observer.disconnect()}};const checkChildren=()=>{if($captcha[0].children.length>0){setTimeout(destroy,1000);return!0}
return!1};let observer=new MutationObserver(function(){checkChildren()});observer.observe($captcha[0],{childList:!0});checkChildren();setTimeout(destroy,10000)})}
function getCookie(name){const value=`; ${document.cookie}`;const parts=value.split(`; ${name}=`);if(parts.length>=2){return parts.pop().split(';').shift()}
return null}